package com.aaron.breeze;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.*;
public class ProtocolTest {
    private byte[] motorState(){ByteBuffer b=ByteBuffer.allocate(20).order(ByteOrder.LITTLE_ENDIAN);b.put(0,(byte)4);b.put(1,(byte)1);b.put(4,(byte)4);b.putShort(5,(short)1500);return b.array();}
    @Test public void continuousTelemetryTracksRunningAndReleased(){byte[] b=motorState();Protocol.MotorReading r=Protocol.decodeMotor(b);assertTrue(r.canJog());assertFalse(r.powered);b[1]=7;b[7]=-1;b[8]=20;ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).putShort(2,(short)1400).putShort(9,(short)80);r=Protocol.decodeMotor(b);assertTrue(r.running);assertFalse(r.canJog());assertEquals(-1,r.direction);assertEquals(20,r.speed);assertEquals(80,r.remainingMs);assertEquals(1500,r.neutral);}
    @Test public void positionalTelemetryCannotEnableContinuousCommands(){byte[] b=motorState();b[4]=3;b[1]=3;ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).putShort(2,(short)1500);Protocol.MotorReading r=Protocol.decodeMotor(b);assertFalse(r.continuous());assertFalse(r.canJog());}
    @Test public void jogWireFormatContainsDirectionSpeedDurationAndNeutral(){for(boolean positive:new boolean[]{true,false}){byte[] b=Protocol.motorJog(positive,100,2000,1600,513);ByteBuffer p=ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);assertEquals(20,b.length);assertEquals(1,b[0]);assertEquals(2,b[1]);assertEquals(513,p.getShort(2)&65535);assertEquals(14,b[4]);assertEquals(positive?1:2,b[5]);assertEquals(100,b[6]&255);assertEquals(2000,p.getShort(7)&65535);assertEquals(1600,p.getShort(9)&65535);}Protocol.motorJog(true,1,20,1400,1);}
    @Test public void invalidJogBoundsRejected(){int[][] bad={{0,100,1500},{101,100,1500},{20,19,1500},{20,2001,1500},{20,100,1399},{20,100,1601}};for(int[] args:bad){try{Protocol.motorJog(true,args[0],args[1],args[2],1);fail("Invalid jog accepted");}catch(IllegalArgumentException expected){}}}
    @Test public void indefiniteRunWireFormatHasZeroDuration(){for(boolean positive:new boolean[]{true,false}){byte[] b=Protocol.motorRun(positive,100,1600,514);ByteBuffer p=ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);assertEquals(20,b.length);assertEquals(17,b[4]);assertEquals(positive?1:2,b[5]);assertEquals(100,b[6]&255);assertEquals(0,p.getShort(7));assertEquals(1600,p.getShort(9)&65535);}Protocol.motorRun(false,1,1400,1);}
    @Test public void indefiniteRunBoundsRejected(){for(int[] args:new int[][]{{0,1500},{101,1500},{20,1399},{20,1601}}){try{Protocol.motorRun(true,args[0],args[1],1);fail("Invalid run accepted");}catch(IllegalArgumentException expected){}}}
    @Test public void indefiniteStateRequiresV5AndAllowsRunningUpdates(){byte[] b=motorState();assertFalse(Protocol.decodeMotor(b).canRunContinuous());b[4]=5;assertTrue(Protocol.decodeMotor(b).canRunContinuous());b[1]=15;b[7]=1;b[8]=50;ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).putShort(2,(short)1750);Protocol.MotorReading r=Protocol.decodeMotor(b);assertTrue(r.continuousRun);assertTrue(r.running);assertTrue(r.canRunContinuous());assertFalse(r.canJog());assertEquals(0,r.remainingMs);b[1]=7;assertFalse(Protocol.decodeMotor(b).canRunContinuous());}
    @Test public void indefiniteStateRejectsTimedRemaining(){byte[] b=motorState();b[4]=5;b[1]=15;b[7]=1;b[8]=50;ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).putShort(2,(short)1750).putShort(9,(short)100);try{Protocol.decodeMotor(b);fail("Indefinite run has remaining time");}catch(IllegalArgumentException expected){}}
    @Test public void stopAndNeutralCommandsHaveNoJog(){byte[] stop=Protocol.control(Protocol.MOTOR_STOP,0,1);assertEquals(15,stop[4]);for(int i=5;i<20;i++)assertEquals(0,stop[i]);byte[] trim=Protocol.motorNeutral(1497,2);assertEquals(16,trim[4]);assertEquals(1497,ByteBuffer.wrap(trim).order(ByteOrder.LITTLE_ENDIAN).getShort(5)&65535);for(int neutral:new int[]{1399,1601}){try{Protocol.motorNeutral(neutral,1);fail("Invalid trim accepted");}catch(IllegalArgumentException expected){}}}
    @Test public void invalidMotorTelemetryRejected(){for(int field:new int[]{4,5,7,8,9}){byte[] b=motorState();ByteBuffer p=ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);switch(field){case 4:b[4]=2;break;case 5:p.putShort(5,(short)1601);break;case 7:b[7]=2;break;case 8:b[8]=101;break;case 9:p.putShort(9,(short)2001);break;}try{Protocol.decodeMotor(b);fail("Invalid motor telemetry accepted");}catch(IllegalArgumentException expected){}}}
    @Test public void physicalDialOrderIsOffHighMediumLow(){Protocol.Config c=new Protocol.Config();byte[] b=Protocol.config(c,42);assertEquals(60,b[10]&255);assertEquals(105,b[11]&255);assertEquals(90,b[12]&255);assertEquals(75,b[13]&255);assertEquals(0,b[19]);assertEquals(20,b.length);}
    @Test public void reversedMountingWorks(){Protocol.Config c=new Protocol.Config();c.offAngle=120;c.highAngle=105;c.mediumAngle=90;c.lowAngle=75;c.validate();}
    @Test(expected=IllegalArgumentException.class) public void wrongDialOrderRejected(){Protocol.Config c=new Protocol.Config();c.offAngle=60;c.lowAngle=75;c.mediumAngle=90;c.highAngle=105;c.validate();}
    @Test(expected=IllegalArgumentException.class) public void crossedThresholdsRejected(){Protocol.Config c=new Protocol.Config();c.low=35;c.validate();}
    @Test(expected=IllegalArgumentException.class) public void nanThresholdRejected(){Protocol.Config c=new Protocol.Config();c.low=Double.NaN;c.validate();}
    @Test public void missingSensorIsNotZero(){byte[] b=new byte[20];b[0]=1;b[11]=60;Protocol.Reading r=Protocol.decode(b,123);assertTrue(Double.isNaN(r.probe));assertTrue(Double.isNaN(r.room));assertEquals(123,r.time);}
    @Test public void signedProbeAndLargeUptime(){ByteBuffer b=ByteBuffer.allocate(20).order(ByteOrder.LITTLE_ENDIAN);b.put(0,(byte)1);b.put(1,(byte)8);b.putShort(4,(short)-500);b.putInt(12,-1);Protocol.Reading r=Protocol.decode(b.array(),10);assertEquals(-5,r.probe,0);assertEquals(4294967295L,r.uptime);}
    @Test public void recordCorruptionRejected(){byte[] b=new byte[20];b[0]=2;b[19]=(byte)Protocol.crc8(b,19);Protocol.validateRecord(b);b[10]^=1;try{Protocol.validateRecord(b);fail();}catch(IllegalArgumentException expected){}}
    @Test public void retirementCursorLittleEndian(){byte[] b=Protocol.retire(0x12345678,1);assertEquals(5,b[1]);assertEquals(0x78,b[4]&255);assertEquals(0x12,b[7]&255);}
}
